@@ -0,0 +1,20 @@
+import { Manifest, Platform } from "./manifest";
+import { TenantConfig } from "./tenant";
+
+export class Session {
+  platform: Platform | null;
+  messages: string[];
+
+  constructor(manifest: Manifest, tenant: TenantConfig) {
+    this.platform = manifest.platform;
+    this.messages = tenant.messageOverrides ?? manifest.platform?.messages ?? [];
+  }
+
+  apply(manifest: Manifest): void {
+    this.platform = manifest.platform;
+  }
+
+  setMessages(messages: string[]): void {
+    this.messages = messages;
+  }
+}

@@ -0,0 +1,9 @@
+export interface Platform {
